-- Somewhere Along the Road: Studio Command Bar bootstrap (generated by tools/build.luau)
-- Paste ALL of this into View > Command Bar in Roblox Studio and press Enter.
-- It installs the game's scripts, builds the town and terrain, then you press Play.
local ok, err = pcall(function()
local function make(class, name, parent, source)
	local existing = parent:FindFirstChild(name)
	if existing then existing:Destroy() end
	local inst = Instance.new(class)
	inst.Name = name
	if source then inst.Source = source end
	inst.Parent = parent
	return inst
end
