local i8 = make("ModuleScript", "BusStopStranger", i7, [======[
--!strict
-- 4. A traveler walks in off the trail and waits at the bus stop. Eventually the Route 9 bus
--    shows up, they climb aboard, and the bus carries on east.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Text = require(ReplicatedStorage:WaitForChild("SomewhereShared"):WaitForChild("Text"))
local EventContext = require(script.Parent.Parent.EventContext)
local Motion = require(script.Parent.Parent.Motion)
local Layout = require(script.Parent.Parent.Parent.World.Layout)
local Vehicles = require(script.Parent.Parent.Parent.World.Vehicles)
local Props = require(script.Parent.Parent.Parent.World.Props)

local rgb = Color3.fromRGB

local LOOKS = {
	{ Skin = rgb(236, 196, 166), Shirt = rgb(150, 110, 80), Pants = rgb(60, 60, 70), Hat = "Fedora", HatColor = rgb(90, 74, 60) },
	{ Skin = rgb(140, 96, 70), Shirt = rgb(200, 120, 90), Pants = rgb(70, 80, 100), Hat = "Bucket", HatColor = rgb(220, 200, 150) },
	{ Skin = rgb(250, 214, 190), Shirt = rgb(110, 140, 170), Pants = rgb(90, 80, 70), Hat = "Cap", HatColor = rgb(170, 60, 50) },
}

return {
	Id = "BusStopStranger",
	Name = "Stranger at the bus stop",
	Resources = { "BusStop", "Road" },
	Cooldown = 900,
	Weight = 8,
	CanRun = function(systems: any): boolean
		local clock = systems.DayNight.GetClock()
		return clock > 7 and clock < 21
	end,
	Run = function(ctx: EventContext.Context)
		local S = ctx.Systems
		local arrive = ctx:Anchor("TravelerArrive")
		local curb = ctx:Anchor("BusStopCurb")
		local bench = ctx:Anchors("BusBench")[1]
		local stop = ctx:Anchor("BusStopRoad")
		if not (arrive and curb and bench and stop) then
			return
		end

		local look = ctx:Pick(LOOKS)
		local traveler = S.NPCs.Spawn({
			Name = "Traveler",
			CFrame = arrive * CFrame.Angles(0, math.rad(-90), 0),
			Skin = look.Skin,
			Shirt = look.Shirt,
			Pants = look.Pants,
			LongSleeves = true,
			Hat = look.Hat,
			HatColor = look.HatColor,
			Talk = false,
		})
		if not traveler then
			return
		end
		ctx:OnCleanup(function()
			traveler:Destroy()
		end)

		-- Talking to them counts as a discovery.
		local index = 0
		S.Interactions.Add(traveler.Root, { ActionText = "Talk", ObjectText = "Traveler", MaxDistance = 9 }, function(player: Player)
			index = index % #Text.NPC.Traveler + 1
			traveler:Say(Text.NPC.Traveler[index])
			S.Discoveries.Award(player, "traveler")
		end)

		local staged = ctx.Options.Seated == true
		if not staged then
			traveler:WalkTo(curb.Position, 30)
		end
		if ctx.Cancelled then
			return
		end
		local suitcase = ctx:Track(Props.suitcase(workspace, bench.CFrame * CFrame.new(4.9, -1.9, 0.3) * CFrame.Angles(0, math.rad(80), 0), rgb(120, 80, 60)))
		if bench:IsA("Seat") and not bench.Occupant then
			if staged then
				-- Already waiting when the camera arrives.
				traveler.Model:PivotTo(bench.CFrame * CFrame.new(0, 2, 0))
			else
				traveler:WalkTo(bench.Position, 6)
			end
			traveler:SitOn(bench)
		end

		if ctx.Options.NoBus then
			while ctx:Wait(1) do
			end
			return
		end
		if not ctx:Wait(ctx.Rng:NextNumber(150, 240)) then
			return
		end

		-- Here comes the bus.
		local start = Vector3.new(-(Layout.Road.MaxX - 20), Layout.Road.Top, Layout.Road.LaneOffset)
		local busModel = ctx:Track(Vehicles.bus(workspace, CFrame.new(start) * CFrame.Angles(0, -math.pi / 2, 0)))
		busModel.Name = "Event_Bus"
		local bus = Motion.Rig(busModel)
		local function stopped(): boolean
			return ctx.Cancelled
		end
		ctx:Sound("Engine", bus.Root, true, 0.35)
		-- Line the bus door (12.6 studs ahead of its centre) up with the curb.
		local stopPos = Vector3.new(curb.Position.X - 12.6, Layout.Road.Top + 0.5, Layout.Road.LaneOffset)
		if not Motion.MoveTo(bus, stopPos - Vector3.new(60, 0, 0), 26, stopped) then
			return
		end
		if not Motion.MoveTo(bus, stopPos, 9, stopped) then
			return
		end

		traveler:Stand()
		traveler:Say(Text.Lines.TravelerBus, 4)
		traveler:WalkTo(Vector3.new(curb.Position.X, curb.Position.Y, Layout.Road.Width / 2 + 1.5), 8)
		if not ctx:Wait(1.5) then
			return
		end
		traveler:Destroy()
		suitcase:Destroy()
		if not ctx:Wait(3) then
			return
		end
		Motion.MoveTo(bus, Vector3.new(Layout.Road.MaxX - 20, Layout.Road.Top + 0.5, Layout.Road.LaneOffset), 24, stopped)
	end,
}
]======])
local i9 = make("ModuleScript", "FunnyIncident", i7, [======[
--!strict
-- 9. A small, harmless, funny moment with the locals:
--    Hollis's lawn mower makes a run for it, or a chicken crosses the road (Dot has questions).

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Text = require(ReplicatedStorage:WaitForChild("SomewhereShared"):WaitForChild("Text"))
local EventContext = require(script.Parent.Parent.EventContext)
local Motion = require(script.Parent.Parent.Motion)
local Props = require(script.Parent.Parent.Parent.World.Props)

local function cancelled(ctx: EventContext.Context): () -> boolean
	return function()
		return ctx.Cancelled
	end
end

local function mower(ctx: EventContext.Context)
	local S = ctx.Systems
	local home = ctx:Anchor("MowerHome")
	local hollis = S.NPCs.Get("Hollis")
	if not home then
		return
	end
	local model = ctx:Track(Props.mower(workspace, home))
	model.Name = "Event_Mower"
	local rig = Motion.Rig(model, true)
	ctx:Sound("Mower", rig.Root, true, 0.5)
	ctx:AwardNearby(function()
		return rig.Root.Position
	end, 45, "runaway_mower")

	if hollis and not hollis.Busy then
		hollis.Busy = true
		ctx:OnCleanup(function()
			hollis.Busy = false
			hollis:GoHome()
		end)
	else
		hollis = nil
	end

	-- The mower wanders off across the road, Hollis close behind.
	local start = home.Position
	local route = {
		start + Vector3.new(0, 0, -20),
		start + Vector3.new(-12, 0, -36),
		start + Vector3.new(-26, 0, -58),
		start + Vector3.new(-30, 0, -70),
	}
	if hollis then
		hollis:Say(Text.Lines.HollisMower)
		hollis.Humanoid.WalkSpeed = 7
		ctx:Spawn(function()
			while not ctx.Cancelled and model.Parent do
				local behind = rig.Root.Position - rig.Root.CFrame.LookVector * 4
				hollis.Humanoid:MoveTo(behind)
				hollis:Play("Walk", true)
				task.wait(0.3)
			end
		end)
	end
	for _, p in route do
		if not Motion.MoveTo(rig, p, 5.5, cancelled(ctx)) then
			return
		end
	end
	if not ctx:Wait(2.5) then
		return
	end
	if hollis then
		hollis.Humanoid.WalkSpeed = 9
		hollis:Say(Text.Lines.HollisMowerCaught)
	end
	if not ctx:Wait(3) then
		return
	end
	-- Walk it back home, slowly, with dignity.
	for i = #route - 1, 1, -1 do
		if not Motion.MoveTo(rig, route[i], 3.5, cancelled(ctx)) then
			return
		end
	end
	Motion.MoveTo(rig, start, 3.5, cancelled(ctx))
	ctx:Wait(2)
end

local function chicken(ctx: EventContext.Context)
	local S = ctx.Systems
	local o = ctx.Options
	local from = (o.From :: Vector3?) or Vector3.new(66, 0, 32)
	local cf = CFrame.lookAt(from, from + Vector3.new(0, 0, -1))
	local model = ctx:Track(Props.chicken(workspace, cf))
	model.Name = "Event_Chicken"
	local rig = Motion.Rig(model, true)
	ctx:Sound("Chicken", rig.Root, false, 0.6)
	ctx:AwardNearby(function()
		return rig.Root.Position
	end, 45, "chicken_crossing")

	local dot = S.NPCs.Get("Dot")
	local dotSpot = o.DotSpot :: CFrame?
	if dot and dotSpot then
		-- Staged: Dot is already out front, watching.
		dot.Busy = true
		ctx:OnCleanup(function()
			dot.Busy = false
			dot:GoHome()
		end)
		dot:Stand()
		dot.Model:PivotTo(dotSpot)
		task.delay((o.DotLineAt :: number?) or 2.5, function()
			if not ctx.Cancelled then
				dot:Say(Text.Lines.DotChicken, 5)
			end
		end)
	elseif dot and not dot.Busy then
		dot.Busy = true
		ctx:OnCleanup(function()
			dot.Busy = false
			dot:GoHome()
		end)
		ctx:Spawn(function()
			local inside = ctx:Anchor("DinerDoorInside")
			local outside = ctx:Anchor("DinerDoorOutside")
			local door = ctx:Find("DinerDoor") :: BasePart?
			if inside and outside then
				for _, name in { "DinerCounterEnd", "DinerFloorMid" } do
					local p = ctx:Anchor(name)
					if p then
						dot:WalkTo(p.Position, 10)
					end
				end
				dot:WalkTo(inside.Position, 14)
				if door then
					S.Interactions.SetDoor(door, true)
				end
				dot:WalkTo(outside.Position, 8)
				dot:Face(rig.Root.Position)
				task.wait(1)
				dot:Say(Text.Lines.DotChicken)
			end
		end)
	end

	-- Little hops, little pauses, all the way across.
	local to = o.To :: Vector3?
	if to then
		-- Staged: one steady trot to the far side.
		if not Motion.MoveTo(rig, to, (o.Speed :: number?) or 5, cancelled(ctx), 0.6) then
			return
		end
	else
		local waypoints = { Vector3.new(65, 0, 14), Vector3.new(63, 0, 2), Vector3.new(62, 0, -10), Vector3.new(60, 0, -22), Vector3.new(57, 0, -40) }
		for _, p in waypoints do
			if not Motion.MoveTo(rig, p, 3.2, cancelled(ctx), 0.6) then
				return
			end
			if not ctx:Wait(ctx.Rng:NextNumber(0.5, 2)) then
				return
			end
		end
	end
	if not ctx:Wait(6) then
		return
	end
	Motion.MoveTo(rig, Vector3.new(64, 0, -110), 4, cancelled(ctx), 0.6)
end

return {
	Id = "FunnyIncident",
	Name = "Funny moment with a local",
	Resources = { "Road", "Hollis", "Dot" },
	Cooldown = 900,
	Weight = 7,
	CanRun = function(systems: any): boolean
		local clock = systems.DayNight.GetClock()
		return clock > 8 and clock < 19
	end,
	Run = function(ctx: EventContext.Context)
		local variant = ctx.Options.Variant
		if variant == "chicken" then
			return chicken(ctx)
		elseif variant == "mower" then
			return mower(ctx)
		end
		if ctx.Systems.NPCs.Available("Hollis") and ctx.Rng:NextNumber() < 0.5 then
			mower(ctx)
		else
			chicken(ctx)
		end
	end,
}
]======])
local i10 = make("ModuleScript", "GoldenSunset", i7, [======[
--!strict
-- 8. A quiet, beautiful sunset. The sky clears and goes gold and pink. Hollis sits on his porch.
--    Anyone who stands still for a little while to watch it gets a small discovery.

local Players = game:GetService("Players")

local EventContext = require(script.Parent.Parent.EventContext)

local STILL_SECONDS = 8

return {
	Id = "GoldenSunset",
	Name = "A quiet, beautiful sunset",
	Resources = { "Weather", "Sky", "Hollis" },
	Cooldown = 1300,
	Weight = function(systems: any): number
		local clock = systems.DayNight.GetClock()
		local w = systems.Weather.Get()
		return if clock > 16.6 and clock < 17.5 and w.Storm < 0.3 then 14 else 0
	end,
	Run = function(ctx: EventContext.Context)
		local S = ctx.Systems
		if ctx.Forced then
			local clock = S.DayNight.GetClock()
			if clock < 16.6 or clock > 18.2 then
				S.DayNight.SetClock(17.05)
			end
		end
		local clear = S.Weather.Override("Clear", 35)
		S.DayNight.SetMood("Sunset", 1, 35)
		ctx:OnCleanup(function()
			S.Weather.Release(clear)
			S.DayNight.SetMood("Sunset", 0, 25)
		end)

		-- Hollis takes a seat on his porch to watch.
		local hollis = S.NPCs.Get("Hollis")
		local porchSeat: Seat? = nil
		local house = ctx:Find("House_S1")
		if house then
			for _, d in house:GetDescendants() do
				if d:IsA("Seat") and d.Name == "BenchSeat" then
					porchSeat = d
				end
			end
		end
		if hollis and not hollis.Busy and porchSeat and not porchSeat.Occupant then
			hollis.Busy = true
			ctx:OnCleanup(function()
				hollis.Busy = false
				hollis:GoHome()
			end)
			ctx:Spawn(function()
				hollis:WalkTo(porchSeat.Position + porchSeat.CFrame.LookVector * 3, 20)
				hollis:WalkTo(porchSeat.Position, 6)
				hollis:SitOn(porchSeat)
			end)
		end

		-- Stand still and watch.
		local lastPos: { [Player]: Vector3 } = {}
		local stillFor: { [Player]: number } = {}
		while not ctx.Cancelled and S.DayNight.GetClock() < 18.9 and S.DayNight.GetClock() > 12 do
			for _, player in Players:GetPlayers() do
				local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
				if root then
					local before = lastPos[player]
					if before and (root.Position - before).Magnitude < 1.2 then
						stillFor[player] = (stillFor[player] or 0) + 1
						if stillFor[player] >= STILL_SECONDS then
							S.Discoveries.Award(player, "quiet_sunset")
						end
					else
						stillFor[player] = 0
					end
					lastPos[player] = root.Position
				end
			end
			if not ctx:Wait(1) then
				return
			end
		end
		S.DayNight.SetMood("Sunset", 0, 40)
		ctx:Wait(20)
	end,
}
]======])
local i11 = make("ModuleScript", "PowerOutage", i7, [======[
--!strict
-- 5. A brief power outage. Everything electric flickers, goes quiet, then hums back to life.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Text = require(ReplicatedStorage:WaitForChild("SomewhereShared"):WaitForChild("Text"))
local EventContext = require(script.Parent.Parent.EventContext)

local function nearSomeone(ctx: EventContext.Context, npcName: string, radius: number): any
	local npc = ctx.Systems.NPCs.Get(npcName)
	if npc and not npc.Busy and ctx:NearestPlayerDistance(npc.Root.Position) < radius then
		return npc
	end
	return nil
end

return {
	Id = "PowerOutage",
	Name = "Brief power outage",
	Resources = { "Power" },
	Cooldown = 1500,
	Weight = function(systems: any): number
		-- Far more noticeable (and more likely) after dark.
		return if systems.DayNight.IsDark() then 9 else 3
	end,
	Run = function(ctx: EventContext.Context)
		local S = ctx.Systems
		ctx:OnCleanup(function()
			S.Net.Set("PowerOn", true)
		end)
		local offAfter = ctx.Options.OffAfter :: number?
		if offAfter and not ctx:Wait(offAfter) then
			return
		end
		S.Lights.Flicker(1.6)
		S.Net.Set("PowerOn", false)
		local marv = nearSomeone(ctx, "Marv", 40)
		if marv then
			marv:Say(Text.Lines.MarvOutage)
		end
		local dot = nearSomeone(ctx, "Dot", 40)
		if dot then
			task.delay(2.5, function()
				dot:Say(Text.Lines.DotOutage)
			end)
		end
